/**
 * Base class for retry strategies
 */
export class RetryStrategy {
    constructor(options?: {});
    maxAttempts: any;
    initialDelay: any;
    maxDelay: any;
    /**
     * Calculate delay for next retry attempt
     * @param {number} attempt - Current attempt number (1-based)
     * @returns {number} - Delay in milliseconds
     */
    getDelay(attempt: number): number;
    /**
     * Check if should retry
     * @param {number} attempt - Current attempt number
     * @returns {boolean}
     */
    shouldRetry(attempt: number): boolean;
}
/**
 * Exponential backoff strategy: delay doubles each attempt
 * Delay = initialDelay * (2 ^ (attempt - 1))
 */
export class ExponentialBackoffStrategy extends RetryStrategy {
    getDelay(attempt: any): number;
}
/**
 * Fixed delay strategy: same delay for all attempts
 */
export class FixedDelayStrategy extends RetryStrategy {
    getDelay(): number;
}
/**
 * Linear backoff strategy: delay increases linearly
 * Delay = initialDelay * attempt
 */
export class LinearBackoffStrategy extends RetryStrategy {
    getDelay(attempt: any): number;
}
/**
 * Retry manager handles retry logic with configurable strategies
 */
export class RetryManager {
    constructor(options?: {});
    options: {
        enabled: boolean;
        maxAttempts: any;
        strategy: any;
        initialDelay: any;
        maxDelay: any;
        retryableErrors: any;
        onRetry: any;
    };
    strategy: ExponentialBackoffStrategy | FixedDelayStrategy | LinearBackoffStrategy;
    retryHistory: Map<any, any>;
    createStrategy(): ExponentialBackoffStrategy | FixedDelayStrategy | LinearBackoffStrategy;
    /**
     * Check if error is retryable
     * @param {Error} error
     * @returns {boolean}
     */
    isRetryableError(error: Error): boolean;
    /**
     * Execute function with retry logic
     * @param {string} ruleId - Rule identifier
     * @param {Function} fn - Async function to execute
     * @returns {Promise<any>}
     */
    execute(ruleId: string, fn: Function): Promise<any>;
    /**
     * Sleep utility
     * @param {number} ms
     * @returns {Promise<void>}
     */
    sleep(ms: number): Promise<void>;
    /**
     * Get retry history for a rule
     * @param {string} ruleId
     * @returns {Array}
     */
    getRetryHistory(ruleId: string): any[];
    /**
     * Clear retry history
     * @param {string} ruleId - Optional specific rule
     */
    clearHistory(ruleId: string): void;
    /**
     * Get statistics
     * @returns {Object}
     */
    getStats(): Object;
}
